Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='defaultconversation', at=datetime(2026, 9, 13, 0, 0, 0), actor='assistant', title='The secretary page and the morning brief land in one fixed conversation named default', body="The secretary page opens, and the morning brief writes into, one fixed conversation whose id is default, opened when first used. It is not the newest conversation, because a side topic would then become tomorrow's default, and it is not a key of the instance file, because no deployment varies it. The daily review and the sweep keep their own dated conversations, since they are the agent's work and not the owner's chat, and a brief written with --new goes to a dated one.", rationale='The owner asked for one default chat in which the agent knows everything, and a fixed name keeps that chat from moving when another conversation is opened.', supersedes=()))